def transform_conn(g, dirs, fill=4):
 from collections import deque
 h,w=len(g),len(g[0]); cnt=Counter(v for row in g for v in row); bg=cnt.most_common(1)[0][0]; out=[row[:] for row in g];seen=set()
 for r in range(h):
  for c in range(w):
   if g[r][c]!=bg or (r,c) in seen:continue
   q=deque([(r,c)]);seen.add((r,c));cells=[];edge=False
   while q:
    x,y=q.popleft();cells.append((x,y));edge |= x in (0,h-1) or y in (0,w-1)
    for dx,dy in dirs:
     xx,yy=x+dx,y+dy
     if 0<=xx<h and 0<=yy<w and g[xx][yy]==bg and (xx,yy) not in seen:seen.add((xx,yy));q.append((xx,yy))
   if not edge:
    for x,y in cells:out[x][y]=fill
 return out
